# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::Handoff::Checkpoint do
  it "digest holds a count and checksum per table and company and a row without company_id is refused" do
    checkpoint_class = Timekeeping::Handoff::Checkpoint
    entry_row = lambda do |id, company_id, duration|
      checkpoint_class::TABLES.fetch("entries").to_h do |column|
        value = { "id" => id, "company_id" => company_id, "duration" => duration, "version" => 2,
                  "note" => "work", "bill_status" => "unbilled" }[column]
        [column, value]
      end
    end
    tables = checkpoint_class::TABLES.keys.index_with { [] }
    tables["entries"] = [entry_row.call(1, 10, 1.5), entry_row.call(2, 10, 2.0), entry_row.call(3, 20, 1.5)]

    digest = checkpoint_class.build(tables: tables).digest

    # "A checkpoint carries a row count and a checksum per table and per company, and every row carries company_id"
    expect(digest.fetch("entries").keys).to contain_exactly(10, 20)
    expect(digest.dig("entries", 10, :count)).to eq(2)
    expect(digest.dig("entries", 20, :count)).to eq(1)
    expect(digest.dig("entries", 10, :checksum)).to be_a(String)
    expect(digest.dig("entries", 10, :checksum)).not_to eq(digest.dig("entries", 20, :checksum))

    without_company = tables.merge("entries" => [entry_row.call(4, nil, 1.0)])
    expect { checkpoint_class.build(tables: without_company) }.to raise_error(/entries/)
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  it "verify reports a duration one bit off only for that table and company" do
    checkpoint_class = Timekeeping::Handoff::Checkpoint
    entry_row = lambda do |id, company_id, duration|
      checkpoint_class::TABLES.fetch("entries").to_h do |column|
        value = { "id" => id, "company_id" => company_id, "duration" => duration, "version" => 3,
                  "note" => "work", "bill_status" => "unbilled" }[column]
        [column, value]
      end
    end
    build = lambda do |company_a_duration|
      tables = checkpoint_class::TABLES.keys.index_with { [] }
      tables["entries"] = [entry_row.call(1, 10, company_a_duration), entry_row.call(2, 20, 0.1 + 0.2)]
      checkpoint_class.build(tables: tables)
    end
    original = build.call(0.1 + 0.2)
    changed = build.call((0.1 + 0.2).next_float)
    expect(checkpoint_class.verify(original)).to eq([])

    # Rows from the changed checkpoint carried under the original checkpoint's digest.
    original_hash = JSON.parse(original.to_json)
    digest_keys = original_hash.keys.grep(/digest/)
    expect(digest_keys).not_to be_empty
    tampered = checkpoint_class.from_json(JSON.generate(JSON.parse(changed.to_json).merge(original_hash.slice(*digest_keys))))

    # "A changed field, or a float differing in its last bit, fails `verify` for that table and company only."
    mismatches = checkpoint_class.verify(tampered)
    expect(mismatches.map { |mismatch| [mismatch[:table], mismatch[:company_id]] }).to eq([["entries", 10]])
  end
end
